From fd12032913a0d056ecb94442db21655f04eb380f Mon Sep 17 00:00:00 2001
From: MaxED <j.maxed@gmail.com>
Date: Sat, 11 May 2019 16:09:42 +0300
Subject: [PATCH] FS_ListFiles(): fixed incorrect list initialization
 introduced in 7cfca78. Fixed some bugs related to FS_ListFiles() numfiles
 handling change introduced in 7cfca78. ui_mp_playersetup.c, ModelCallback():
 update numitemnames to make SpinControl_DoSlide correctly wrap around when
 navigating backwards. ui_mp_playersetup.c, pmicmpfnc(): sort by male, female,
 cyborg then alphabetical. ui_mp_playersetup.c: rewritten parts of
 PlayerConfig_ScanDirectories() for clarity.


diff --git a/ui/ui_mp_playersetup.c b/ui/ui_mp_playersetup.c
index 26c20fc..0af4752 100644
--- a/ui/ui_mp_playersetup.c
+++ b/ui/ui_mp_playersetup.c
@@ -81,6 +81,7 @@ static void ModelCallback(void *unused)
 	char scratch[MAX_QPATH];

 	s_player_skin_box.itemnames = s_pmi[s_player_model_box.curvalue].skindisplaynames;
+	s_player_skin_box.numitemnames = s_pmi[s_player_model_box.curvalue].nskins; //mxd. Added to make SpinControl_DoSlide correctly wrap around when navigating backwards
 	s_player_skin_box.curvalue = 0;

 	// Only register model and skin on starup or when changed
@@ -179,32 +180,31 @@ static qboolean IsValidSkin(char **filelist, int numFiles, int index)
 	return false;
 }

-static qboolean PlayerConfig_ScanDirectories(void)
+static void PlayerConfig_ScanDirectories(void)
 {
-	char findname[1024];
-	char scratch[1024];
-	int ndirs = 0;
-	char **dirnames;
 	char *path = NULL;
-
+	
 	s_numplayermodels = 0;

 	// Loop back to here if there were no valid player models found in the selected path
-	do
+	while(true)
 	{
+		int ndirs;
+		char **dirnames = NULL;
+		
 		// Get a list of directories
-		do 
+		while((path = FS_NextPath(path)) != NULL)
 		{
-			path = FS_NextPath(path);
+			char findname[1024];
 			Com_sprintf(findname, sizeof(findname), "%s/players/*.*", path);

 			dirnames = FS_ListFiles(findname, &ndirs, SFF_SUBDIR, 0);
 			if (dirnames)
 				break;
-		} while (path);
+		}

-		if (!dirnames)
-			return false;
+		if (dirnames == NULL)
+			return;

 		// Go through the subdirectories
 		int npms = min(ndirs, MAX_PLAYERMODELS);
@@ -235,6 +235,7 @@ static qboolean PlayerConfig_ScanDirectories(void)
 				continue; // todo: add any skins for this model not already listed to skindisplaynames

 			// Verify the existence of tris.md2
+			char scratch[1024];
 			Q_strncpyz(scratch, dirnames[i], sizeof(scratch));
 			Q_strncatz(scratch, "/tris.md2", sizeof(scratch));
 			if (!Sys_FindFirst(scratch, 0, SFF_SUBDIR | SFF_HIDDEN | SFF_SYSTEM))
@@ -262,36 +263,34 @@ static qboolean PlayerConfig_ScanDirectories(void)

 			// Count valid skins, which consist of a skin with a matching "_i" icon
 			int nskins = 0;
-			for (int k = 0; k < nimagefiles - 1; k++) //TODO: mxd. Why nimagefiles - 1, not nimagefiles?
+			for (int k = 0; k < nimagefiles; k++)
 				if (IsValidSkin(imagenames, nimagefiles, k))
 					nskins++;

-			if (!nskins)
+			if (nskins == 0)
 				continue;

+			// Add extra empty item at the end, because Menu_AddItem() counts number of spincontrol items by counting itemnames to '\0' item
 			char **skinnames = malloc(sizeof(char *) * (nskins + 1));
 			memset(skinnames, 0, sizeof(char *) * (nskins + 1));

 			// Copy the valid skins
-			if (nimagefiles > 0)
+			int skinindex = 0;
+			for (int k = 0; k < nimagefiles; k++)
 			{
-				int skinindex = 0;
-				for (int k = 0; k < nimagefiles - 1; k++)
+				if (IsValidSkin(imagenames, nimagefiles, k))
 				{
-					if (IsValidSkin(imagenames, nimagefiles, k))
-					{
-						char *a2 = strrchr(imagenames[k], '/');
-						char *b2 = strrchr(imagenames[k], '\\');
-						char *c2 = max(a2, b2);
+					char *a2 = strrchr(imagenames[k], '/');
+					char *b2 = strrchr(imagenames[k], '\\');
+					char *c2 = max(a2, b2);

-						Q_strncpyz(scratch, c2 + 1, sizeof(scratch));
+					Q_strncpyz(scratch, c2 + 1, sizeof(scratch));

-						if (strrchr(scratch, '.'))
-							*strrchr(scratch, '.') = 0;
+					if (strrchr(scratch, '.'))
+						*strrchr(scratch, '.') = 0;

-						skinnames[skinindex] = strdup(scratch);
-						skinindex++;
-					}
+					skinnames[skinindex] = strdup(scratch);
+					skinindex++;
 				}
 			}

@@ -314,11 +313,7 @@ static qboolean PlayerConfig_ScanDirectories(void)

 		if (dirnames)
 			FS_FreeFileList(dirnames, ndirs);
-
-	// If no valid player models found in path, try next path, if there is one
-	} while (path);	// (s_numplayermodels == 0 && path);
-
-	return true; //** DMP warning fix
+	}
 }

 static int pmicmpfnc(const void *_a, const void *_b)
@@ -326,7 +321,7 @@ static int pmicmpfnc(const void *_a, const void *_b)
 	const playermodelinfo_s *a = (const playermodelinfo_s *) _a;
 	const playermodelinfo_s *b = (const playermodelinfo_s *) _b;

-	// Sort by male, female, then alphabetical
+	// Sort by male, female, cyborg then alphabetical
 	if (strcmp(a->directory, "male") == 0)
 		return -1;
 	if (strcmp(b->directory, "male") == 0)
@@ -337,6 +332,11 @@ static int pmicmpfnc(const void *_a, const void *_b)
 	if (strcmp(b->directory, "female") == 0)
 		return 1;

+	if (strcmp(a->directory, "cyborg") == 0) //mxd
+		return -1;
+	if (strcmp(b->directory, "cyborg") == 0)
+		return 1;
+
 	return strcmp(a->directory, b->directory);
 }

-- 
2.25.1



diff --git a/qcommon/files.c b/qcommon/files.c
index 0737bce..33c3da3 100644
--- a/qcommon/files.c
+++ b/qcommon/files.c
@@ -1137,7 +1137,7 @@ static void FS_AddGameDirectory(const char *dir)
 			return;

 		// Add the ones, which don't match pakX naming sceme
-		for (int i = 0; i < numfiles; i++) //BUG? mxd. This counted to numfiles - 1 in KMQ2. Why?
+		for (int i = 0; i < numfiles; i++)
 		{
 			qboolean numberedpak = false;

@@ -1526,15 +1526,17 @@ void FS_ExecAutoexec(void)
 	Sys_FindClose();
 }

+//mxd. Returns number of matching files, not number of matching files + 1, like in Vanilla!
 char **FS_ListFiles(char *findname, int *numfiles, unsigned musthave, unsigned canthave)
 {
 	int nfiles = 0;
-
+	
 	// Count number of matching files
 	char *filename = Sys_FindFirst(findname, musthave, canthave);
 	while (filename != NULL)
 	{
-		if (filename[strlen(filename) - 1] != '.')
+		// Sys_FindFirst / Sys_FindNext can return a relative path to current ("findname\.") or parent ("findname\..") directory. Skip those.
+		if (filename[strlen(filename) - 1] != '.') 
 			nfiles++;

 		filename = Sys_FindNext(musthave, canthave);
@@ -1547,13 +1549,14 @@ char **FS_ListFiles(char *findname, int *numfiles, unsigned musthave, unsigned c
 	if (nfiles == 0)
 		return NULL;

-	// Fill list with matching filenames
-	const int listsize = sizeof(char *) * (nfiles + 1); // Add space for a guard
+	// Allocate list
+	const size_t listsize = sizeof(char *) * nfiles;
 	char **list = malloc(listsize);
 	memset(list, 0, listsize);

+	// Fill list with matching filenames
 	filename = Sys_FindFirst(findname, musthave, canthave);
-	for (int i = 0; i < nfiles && filename != NULL; i++)
+	for(int i = 0; filename != NULL;)
 	{
 		if (filename[strlen(filename) - 1] != '.')
 		{
@@ -1561,6 +1564,7 @@ char **FS_ListFiles(char *findname, int *numfiles, unsigned musthave, unsigned c
 #ifdef _WIN32
 			strlwr(list[i]);
 #endif
+			i++;
 		}

 		filename = Sys_FindNext(musthave, canthave);
@@ -1640,10 +1644,10 @@ static void FS_Dir_f(void)
 		char **dirnames = FS_ListFiles(findname, &ndirs, 0, 0);
 		if (dirnames)
 		{
-			for (int i = 0; i < ndirs-1; i++)
+			for (int i = 0; i < ndirs; i++)
 			{
-				if (strrchr(dirnames[i], '/' ))
-					Com_Printf("%s\n", strrchr(dirnames[i], '/') + 1 );
+				if (strrchr(dirnames[i], '/'))
+					Com_Printf("%s\n", strrchr(dirnames[i], '/') + 1);
 				else
 					Com_Printf("%s\n", dirnames[i]);


diff --git a/ui/ui_local.h b/ui/ui_local.h
index e928d04..da1f2d5 100644
--- a/ui/ui_local.h
+++ b/ui/ui_local.h
@@ -117,7 +117,7 @@ typedef struct

 	int curvalue;

-	const char **itemnames;
+	const char **itemnames; // Last item is expected to be "\0"
 	int numitemnames;
 } menulist_s;

