static qboolean IconOfSkinExists(char *skin, char **files, int nfiles, char *suffix)
{
	char scratch[1024];

	Q_strncpyz(scratch, skin, sizeof(scratch));
	*strrchr(scratch, '.') = 0;
	Q_strncatz(scratch, suffix, sizeof(scratch));

	for (int i = 0; i < nfiles; i++)
